 const reserve=Number(profile.operating?.truck?.escrow||0);metric(e,'Planned reserve at saved per-mile rate',Number.isFinite(reserve)&&reserve>=0?usd(Math.round(d.miles*reserve*100)):'Not available');const labels={principal:'Principal repayments',capital:'Capital purchases',escrow_out:'Escrow contributions',escrow_in:'Escrow releases',owner_draw:'Owner withdrawals',owner_contribution:'Owner contributions / advances',sales_tax:'Sales tax collected',sales_tax_paid:'Sales tax remitted',savings_out:'Savings transfers out',savings_in:'Savings transfers in'};categories(e,Object.fromEntries(Object.entries(d.transfers).filter(([k])=>!k.startsWith('escrow_')).map(([k,v])=>[labels[k]||k,v])));el(e,'small','Escrow balances reflect recorded movements through the selected end date. Planned reserves are estimates, not posted expenses.');
