 for(const b of (profile.bills||[]).filter(x=>/truck|lease|trailer/i.test(x.name||''))){const due=Planning.nextDate(b,today());if(due)metric(leasesCard,b.name,due+' · '+(b.variable&&b.variable!=='fixed'?'variable':usd(F.cents(b.amount||'0'))));}
