 if(links.length){name.readOnly=true;el(p,'small','Truck name is locked to preserve linked financial and mileage records. Other fields can still be edited.');}
 button(p,'Save changes',async()=>{const n=requireText(value(name),'truck name');if(n.length>100||data.trucks.some(x=>x.id!==t.id&&x.name.toLowerCase()===n.toLowerCase()))throw Error('Use a unique truck name up to 100 characters.');if(n!==t.name&&T.truckDependencies(data,rows,profile,t.id).length)throw Error('Truck name cannot change while records are linked.');const raw=value(starting);if(raw&&!/^\d+$/.test(raw))throw Error('Enter starting miles as a nonnegative whole odometer reading.');const next={...t,name:n,note:value(vin)};if(raw){const miles=T.num(raw,'starting miles');if(!Number.isSafeInteger(miles))throw Error('Enter a valid whole odometer reading.');next.startingMiles=miles;}else if(Number.isFinite(t.startingMiles))throw Error('Enter starting miles to retain the odometer baseline.');await save({...data,trucks:data.trucks.map(x=>x.id===t.id?next:x)});if(truck===t.name)truck=n;render();say('Truck updated.');});
