function reconcile(){syncLines();mustTruck(s.truck);const q=T.settlement(s);summary.replaceChildren();for(const [k,v] of [['Gross revenue',q.gross],['Other cash credits',q.credits],['Deductions',q.deductions],['Calculated net',q.net],['Statement net',q.stated],['Difference',q.difference]])metric(summary,k,usd(v));return q;}
button(p,'Reconcile totals',reconcile);button(p,'Save draft',async()=>{if(readingDoc)throw Error('Wait for the attachment to finish loading.');syncLines();mustTruck(s.truck);requireText(s.number,'settlement number');requireText(s.carrier,'carrier');T.requireDate(s.date);if(s.lines.length>300)throw Error('Maximum 300 lines.');if(T.duplicate(s,data.settlements))throw Error('Duplicate statement number or document.');await save({...data,settlements:replaceRecord(data.settlements,s)});render()});
