function ruleEditor(){const p=editor('Custom categorization rules');el(p,'p','Case-insensitive description contains. First matching rule wins. Rules suggest a category; you must review each statement.');const f={match:input(p,'Description contains'),category:input(p,'Category'),classification:input(p,'Classification','','text',Object.keys(F.classes).filter(k=>F.classes[k][1]))};button(p,'Add rule',async()=>{const r=vals(f);requireText(r.match,'match text');requireText(r.category,'category');await save({...data,rules:[...data.rules,{...r,id:id()}]});ruleEditor()});for(const r of data.rules){el(p,'p',r.match+' → '+r.category+' ('+r.classification+')');button(p,'Remove rule '+r.match,async()=>{await save({...data,rules:data.rules.filter(x=>x.id!==r.id)});ruleEditor()})}button(p,'Back',render)}
