if(def.excluded.length)el(p,'small','Excluded to avoid duplicate operating costs: '+def.excluded.join(', '));
function reset(){const mult=period.value==='trip'?Math.max(0,T.num(days.value))/7:1;for(const [k,v] of Object.entries(fields))v.value=['fixed','extra','fixedReserve','goal'].includes(k)?(Number(def[k])*mult).toFixed(2):def[k];}
if(period.value==='trip')reset();button(p,'Reset saved defaults / prorate fixed costs',reset);period.onchange=reset;days.onchange=()=>{if(period.value==='trip')reset()};const out=card(p,'Results');function evaluate(){const v=vals(fields),q=T.calculate(v);out.replaceChildren();el(out,'h3','Estimated results');for(const [k,n] of [['Revenue',q.gross],['Empty mile revenue',q.emptyRevenue],['Fuel cost',q.fuelCost],['Dispatch fees',q.dispatchCost],['Operating cost',q.cost],['Net profit',q.net],['Reserves and other non-expense cash allocations',q.held],['Cash after reserve',q.available],['Deadhead fuel cost',q.deadheadCost],['Fuel surcharge revenue',q.fscRevenue],['Downtime contribution lost',q.downtimeCost],['Alternative fuel cost',q.alternativeFuelCost],['Savings from alternate discount',q.discountSavings]])metric(out,k,usd(n));for(const [k,n] of [['Revenue / total mile',q.rpm],['Cost / total mile',q.cpm],['Profit / total mile',q.ppm],['Fuel / total mile',q.fuelPerMile],['Break-even / loaded mile',q.breakEvenLoaded],['Required rate / loaded mile incl. goal/reserve',q.requiredLoaded]])metric(out,k,rate(n));metric(out,'Required total miles at same loaded ratio and rates',q.requiredMiles===null?'No attainable target':q.requiredMiles);if(period.value==='week'){metric(out,'Monthly profit estimate',usd(q.monthly));metric(out,'Annual profit estimate',usd(q.annual))}metric(out,'Gallons',q.gallons.toFixed(2));return {v,q};}
